package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class CatalogSelectionTest {
 private JSONObject item(String name,String year,long steam)throws Exception{return new JSONObject().put("nome",name).put("ano",year).put("steam_appid",steam).put("categoria","jogos");}
 @Test public void identifiesKnownOwnershipWithoutCollapsingRemakesOrEditions()throws Exception{JSONArray own=new JSONArray().put(item("Control","2019",10));assertEquals("owned",CatalogSelection.match(item("Control","2019",10),false,0,own).state);assertEquals("new",CatalogSelection.match(item("Control Ultimate Edition","2020",11),false,0,own).state);JSONObject remake=item("Control","2020",11);CatalogSelection.Match match=CatalogSelection.match(remake,false,0,own);assertEquals("variant",match.state);assertEquals("Control (2020)",CatalogSelection.qualified(remake,false,0,match));assertEquals("variant",CatalogSelection.match(item("Control","2019",11),false,0,own).state);assertEquals("possible",CatalogSelection.match(item("Control","",0),false,0,own).state);assertEquals("owned",CatalogSelection.match(item("Control","2020",0),false,0,new JSONArray().put(item("Control (2020)","2020",0))).state);}
 @Test public void metadataAndUnicodeDoNotInventPlatformsOrMergeUnrelatedTitles()throws Exception{assertEquals("new",CatalogSelection.match(item("新しいゲーム","2020",0),false,0,new JSONArray().put(item("違うゲーム","2020",0))).state);assertTrue(CatalogSelection.meta(item("Jogo Remastered","2020",0),false,0).contains("Remaster"));assertTrue(CatalogSelection.meta(item("Sem ano","",0),false,0).contains("Ano não informado"));assertTrue(CatalogSelection.meta(item("Sem plataformas","2020",0),false,0).contains("Plataformas não informadas"));}
}
